对大尺寸图像，批量转化为缩略图的 python 脚本
# -*- coding: utf-8 -*-&quot;&quot;&quot;将远程 BMP 图像批量生成 PNG 缩略图并导出到本地。远程目录只读，本脚本只读取远程、写入本地输出目录。支持从 config.txt 中按奇偶行读取多组 (REMOTE_DIR, DATE_NAME) 批量处理。&quot;&quot;&quot;import osimport sysfrom html import escapefrom concurrent.futures import ThreadPoolExecutor, as_completedfrom PIL import Image# ---------- 配置 ----------CONFIG_FILE = &quot;config.txt&quot;      # 配置文件路径（奇数行 REMOTE_DIR，偶数行 DATE_NAME）THUMB_WIDTH = 400              # 缩略图宽度（px），高度等比MAX_WORKERS = 8                # 多线程线程数（加速网络传输读取）OUTPUT_ROOT = os.path.dirname(os.path.abspath(__file__))# ---------------------------def load_config(config_path):    &quot;&quot;&quot;读取 txt 配置文件，奇数行为 REMOTE_DIR，偶数行为 DATE_NAME&quot;&quot;&quot;    if not os.path.exists(config_path):        print(f&quot;[错误] 找不到配置文件: &#123;config_path&#125;&quot;)        print(&quot;请在脚本同目录下创建 config.txt，格式如下：&quot;)        print(&quot;第一行 (REMOTE_DIR): \\server\share\path1&quot;)        print(&quot;第二行 (DATE_NAME) : 20250915&quot;)        sys.exit(1)    with open(config_path, &quot;r&quot;, encoding=&quot;utf-8&quot;) as f:        lines = [line.strip() for line in f if line.strip() and not line.strip().startswith(&quot;#&quot;)]    if len(lines) % 2 != 0:        print(&quot;[警告] 配置文件有效行数为奇数，最后一行缺失配对的 DATE_NAME，将被忽略！&quot;)        lines = lines[:-1]    tasks_config = []    for i in range(0, len(lines), 2):        remote_dir = lines[i]        date_name = lines[i + 1]        tasks_config.append((remote_dir, date_name))    return tasks_configdef process_single_image(args):    &quot;&quot;&quot;单张图片处理逻辑，供线程池并发调用&quot;&quot;&quot;    src, out_path, thumb_rel_path, thumb_width = args    try:        with open(src, &quot;rb&quot;) as fh:            img = Image.open(fh)            img.load()        w, h = img.size        if w &gt; thumb_width:            new_w = thumb_width            new_h = round(h * (thumb_width / w))        else:            new_w, new_h = w, h        img = img.resize((new_w, new_h), Image.LANCZOS)        if img.mode != &quot;RGB&quot;:            img = img.convert(&quot;RGB&quot;)        img.save(out_path, &quot;PNG&quot;)        return True, src, thumb_rel_path, None    except Exception as e:        return False, src, None, str(e)def process_batch(remote_dir, date_name):    &quot;&quot;&quot;处理一组 (REMOTE_DIR, DATE_NAME) 任务&quot;&quot;&quot;    print(f&quot;
==================================================&quot;)    print(f&quot;开始处理任务: [&#123;date_name&#125;]&quot;)    print(f&quot;远程路径: &#123;remote_dir&#125;&quot;)    print(f&quot;==================================================&quot;)    out_dir   = os.path.join(OUTPUT_ROOT, date_name)    thumb_rel = &quot;thumbs&quot;    thumb_dir = os.path.join(out_dir, thumb_rel)    os.makedirs(thumb_dir, exist_ok=True)    try:        files = sorted(f for f in os.listdir(remote_dir) if f.lower().endswith(&quot;.bmp&quot;))    except FileNotFoundError as e:        print(f&quot;[错误] 无法访问远程目录: &#123;e&#125;&quot;)        return    except PermissionError as e:        print(f&quot;[错误] 拒绝访问，请检查权限或网络登录凭据: &#123;e&#125;&quot;)        return    total = len(files)    if total == 0:        print(&quot;[提示] 该远程目录下未找到 BMP 文件。&quot;)        return    print(f&quot;共发现 &#123;total&#125; 个 BMP 文件，启动 &#123;MAX_WORKERS&#125; 线程处理中...&quot;)    tasks = []    for name in files:        src      = os.path.join(remote_dir, name)        out_name = os.path.splitext(name)[0] + &quot;.png&quot;        out_path = os.path.join(thumb_dir, out_name)        rel_path = os.path.join(thumb_rel, out_name)        tasks.append((src, out_path, rel_path, THUMB_WIDTH))    ok, fail = 0, 0    records = []    # 使用线程池加速远程文件 IO 读取    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:        futures = [executor.submit(process_single_image, task) for task in tasks]        for i, future in enumerate(as_completed(futures), 1):            success, src, rel_path, err_msg = future.result()            if success:                ok += 1                records.append((src, rel_path))            else:                fail += 1                print(f&quot;  [失败] &#123;os.path.basename(src)&#125;: &#123;err_msg&#125;&quot;)            if i % 20 == 0 or i == total:                print(f&quot;  进度 &#123;i&#125;/&#123;total&#125;&quot;)    # 按文件名重新排序记录    records.sort(key=lambda x: x[1])    print(f&quot;任务 [&#123;date_name&#125;] 完成：成功 &#123;ok&#125;，失败 &#123;fail&#125;。缩略图目录: &#123;thumb_dir&#125;&quot;)    # 生成预览 HTML    html_path = os.path.join(out_dir, &quot;index.html&quot;)    make_html(html_path, date_name, records)    print(f&quot;预览页: &#123;html_path&#125;&quot;)def make_html(path, date_name, records):    cards = []    for _src, tp in records:        base = os.path.basename(tp)        # 替换斜杠确保网页路径格式正确        web_tp = tp.replace(&quot;\&quot;, &quot;/&quot;)        cards.append(            f&#x27;&lt;a class=&quot;card&quot; href=&quot;&#123;escape(web_tp)&#125;&quot; target=&quot;_blank&quot;&gt;&#x27;            f&#x27;&lt;img src=&quot;&#123;escape(web_tp)&#125;&quot; loading=&quot;lazy&quot; alt=&quot;&#123;escape(base)&#125;&quot;/&gt;&#x27;            f&#x27;&lt;div class=&quot;cap&quot;&gt;&#123;escape(base)&#125;&lt;/div&gt;&lt;/a&gt;&#x27;        )    cards_html = &quot;
&quot;.join(cards)    html = f&quot;&quot;&quot;&lt;!DOCTYPE html&gt;&lt;html lang=&quot;zh&quot;&gt;&lt;head&gt;&lt;meta charset=&quot;utf-8&quot;/&gt;&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;/&gt;&lt;title&gt;&#123;escape(date_name)&#125; 缩略图预览&lt;/title&gt;&lt;style&gt;body&#123;&#123;font-family:sans-serif;margin:20px;background:#1e1e1e;color:#ddd&#125;&#125;h1&#123;&#123;font-size:18px;margin-bottom:14px&#125;&#125;.grid&#123;&#123;display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px&#125;&#125;.card&#123;&#123;background:#2c2c2c;border:1px solid #444;border-radius:6px;overflow:hidden;text-decoration:none;color:#ddd&#125;&#125;.card img&#123;&#123;width:100%;height:180px;object-fit:contain;background:#000;display:block&#125;&#125;.cap&#123;&#123;font-size:11px;padding:6px 8px;word-break:break-all&#125;&#125;&lt;/style&gt;&lt;/head&gt;&lt;body&gt;&lt;h1&gt;&#123;escape(date_name)&#125; 共 &#123;len(records)&#125; 张&lt;/h1&gt;&lt;div class=&quot;grid&quot;&gt;&#123;cards_html&#125;&lt;/div&gt;&lt;/body&gt;&lt;/html&gt;&quot;&quot;&quot;    with open(path, &quot;w&quot;, encoding=&quot;utf-8&quot;) as f:        f.write(html)def main():    config_path = os.path.join(OUTPUT_ROOT, CONFIG_FILE)    tasks_config = load_config(config_path)    print(f&quot;成功载入 &#123;len(tasks_config)&#125; 组处理任务。&quot;)    for remote_dir, date_name in tasks_config:        process_batch(remote_dir, date_name)    print(&quot;
[全部完成] 所有配置任务均已处理完毕！&quot;)if __name__ == &quot;__main__&quot;:    main()
